from docx import Document
from docx.shared import Pt, RGBColor, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.enum.section import WD_ORIENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(0.8)
sec.top_margin = sec.bottom_margin = Inches(0.8)
st = doc.styles["Normal"]
st.font.name = "Calibri"; st.font.size = Pt(10)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Calibri")
for nm, sz in (("Heading 1", 14), ("Heading 2", 12), ("Heading 3", 11)):
    s = doc.styles[nm]; s.font.name = "Calibri"; s.font.size = Pt(sz); s.font.color.rgb = RGBColor(0x1F, 0x3A, 0x5F)

def shade(cell, color):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd"); shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), color)
    tcPr.append(shd)

def rich(par, text):
    # **bold** markup
    parts = text.split("**")
    for i, p in enumerate(parts):
        if p:
            r = par.add_run(p); r.bold = (i % 2 == 1)
    return par

def P(text="", bold=False, italic=False, size=None, align=None, space_after=4):
    p = doc.add_paragraph()
    if bold or italic:
        r = p.add_run(text); r.bold = bold; r.italic = italic
        if size: r.font.size = Pt(size)
    else:
        rich(p, text)
        if size:
            for r in p.runs: r.font.size = Pt(size)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_after = Pt(space_after)
    return p

def B(text, level=0):
    p = doc.add_paragraph(style="List Bullet" if level == 0 else "List Bullet 2")
    rich(p, text); p.paragraph_format.space_after = Pt(2)
    return p

def H(text, lvl=1):
    return doc.add_heading(text, level=lvl)

def T(headers, rows, widths=None, hdr_color="1F3A5F", font=9):
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = "Table Grid"; t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ""
        r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(font); r.font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        shade(c, hdr_color)
    # repeat header row
    trPr = t.rows[0]._tr.get_or_add_trPr(); th = OxmlElement("w:tblHeader"); th.set(qn("w:val"), "true"); trPr.append(th)
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            lines = str(v).split("\n")
            for j, ln in enumerate(lines):
                par = cells[i].paragraphs[0] if j == 0 else cells[i].add_paragraph()
                rich(par, ln)
                for r in par.runs: r.font.size = Pt(font)
                par.paragraph_format.space_after = Pt(1)
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths):
                row.cells[i].width = Inches(w)
    doc.add_paragraph().paragraph_format.space_after = Pt(2)
    return t

def TERMS(rows):
    return T(["Term", "PSA Ref.", "Extracted Provision (amounts, dates, deadlines)"], rows, widths=[1.45, 0.85, 4.6])
